func (s *Store) DeleteTask(ctx context.Context, externalID string) (bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	externalID = strings.TrimSpace(externalID)
	if externalID == "" {
		return false, nil
	}
	res, err := s.db.ExecContext(ctx, `DELETE FROM task_queue WHERE external_id = ?`, externalID)
	if err != nil {
		return false, err
	}
	_, _ = s.db.ExecContext(ctx, `DELETE FROM autopilot_rounds WHERE task_key = ?`, externalID)
	n, _ := res.RowsAffected()
	return n > 0, nil
}

